/** What each kind means. Shown in the edge panel and handed to Claude
 *  wherever it proposes an edge, so its labels match the curated graph's. */
export const EDGE_KIND_DEFS = {
  'kinase-substrate': 'a protein kinase phosphorylates the target.',
  'enzyme-substrate': 'any other enzyme acts on the target (E3 ligase / ubiquitination, protease or secretase cleavage, phosphatase, other PTM or processing).',
  'transcriptional':  "a transcription factor or co-activator controls the target gene's expression.",
  'receptor-ligand':  'receptor and ligand, or receptor and cargo.',
  'complex':          'stable complex or direct binding partners.',
  'modifier':         'genetic modifier of penetrance, onset or severity.',
  'shared-mechanism': 'same pathway or process, no direct documented interaction.',
  'shared-disease':   'co-implicated in the same disease or phenotype, no shared mechanism shown.',
  'opposes':          'antagonistic effects on the same process.',
};

/** Kinds whose edges read actor → target. */
export const DIRECTIONAL_KINDS = new Set(['kinase-substrate', 'enzyme-substrate', 'transcriptional']);

export const EDGE_KIND_GUIDE =
  'Edge kinds. Pick the most specific that applies. Directional kinds run actor → target, so "from" is the kinase, enzyme or transcription factor.\n' +
  Object.entries(EDGE_KIND_DEFS).map(([k, d]) => `- ${k}: ${d}`).join('\n') +
  '\n- none: no documented connection.';

